export const LENGTH_ELEVATION_SUFFIXES: readonly string[] = [".radius", ".x", ".y", ".blur"];

/** The canonical CSS custom property for a token path: `--pl-` prefix, `.` → `-`.
 *  The `dark.` scheme prefix is stripped — the dark variant overrides the same
 *  variable inside a media query. */
export function tokenToCssVar(path: string): string {
  const bare = path.startsWith(DARK_PREFIX) ? path.slice(DARK_PREFIX.length) : path;
  return VAR_PREFIX + bare.replace(/[^A-Za-z0-9_-]/g, "-");
}

/** Whether a token path selects the dark variant. */
export function isDarkToken(path: string): boolean {
  return path.startsWith(DARK_PREFIX);
}

/** Token paths whose F32 values are CSS lengths (emitted with `px`). */
export function isLengthToken(path: string): boolean {
  for (const prefix of LENGTH_PREFIXES) {
   if (path.startsWith(prefix)) return true;
  }
  for (const [prefix, suffix] of LENGTH_PREFIX_SUFFIX) {
   if (path.startsWith(prefix) && path.endsWith(suffix)) return true;
  }
  if (LENGTH_EXACT.includes(path)) return true;
  return path.startsWith("elevation.") && LENGTH_ELEVATION_SUFFIXES.some((s) => path.endsWith(s));
}

/** Resolve a `DESIGN_TOKEN` property reference to a CSS expression: the
*  generative `space.<N>` family resolves to `calc(var(--pl-space-base) * N)`. */
export function resolveTokenCssRef(path: string): string {
  const bare = path.startsWith(DARK_PREFIX) ? path.slice(DARK_PREFIX.length) : path;
  if (bare.startsWith(SPACE_FAMILY)) {
   const rest = bare.slice(SPACE_FAMILY.length);
   if (rest.length > 0 && !Number.isNaN(Number(rest))) {
    return `calc(var(--pl-space-base) * ${rest})`;
   }
  }
  return `var(${tokenToCssVar(bare)})`;
}

