 function setFilterPart(el: HTMLElement, prefix: string, value: number | string): void {
   const parts = FILTERS.get(el) ?? [];
   const i = parts.findIndex((p) => p.startsWith(prefix));
   const part = `${prefix}${value})`;
   if (i >= 0) {
