/** The semantic tag a `(component, role)` pair resolves to, or null when the
 *  element keeps its default shell tag. */
export function semanticTag(component: number, role: number): string | null {
  if (!GENERIC_COMPONENTS.includes(component)) return null;
  const found = ROLE_TAGS.find((r) => r.role === role);
  return found ? found.tag : null;
}

