export type ShellKind = "generic" | "native" | "other";
export function semanticTag(kind: ShellKind, role: number): string | null {
  if (kind !== "generic") return null;
  const found = ROLE_TAGS.find((r) => r.role === role);
  return found ? found.tag : null;
}
export function ariaRole(kind: ShellKind, role: number): string | null {
  if (kind === "native") return null;
  const tagged = ROLE_TAGS.find((r) => r.role === role);
  if (tagged) {
    return kind === "generic" ? null : tagged.aria;
  }
  const found = ROLE_ARIA.find(([r]) => r === role);
  return found ? found[1] : null;
}
